function i18nNormalizeLang(lang) {
  const base = String(lang || '').toLowerCase().split('-')[0];
  return I18N_LANGUAGES[base] ? base : I18N_DEFAULT_LANG;
}

function getStoredLanguage() {
  try {
    return i18nNormalizeLang(localStorage.getItem(I18N_STORAGE_KEY) || I18N_DEFAULT_LANG);
  } catch {
    return I18N_DEFAULT_LANG;
  }
}

function setLanguage(lang) {
  const next = i18nNormalizeLang(lang);
  try {
    localStorage.setItem(I18N_STORAGE_KEY, next);
  } catch {}
  window.location.reload();
}

function getCurrentLanguage() {
  return getStoredLanguage();
}

function t(key, params = {}) {
  const lang = getCurrentLanguage();
  const raw = (I18N_MESSAGES[lang] && I18N_MESSAGES[lang][key])
    || (I18N_MESSAGES.es && I18N_MESSAGES.es[key])
    || key;
  return Object.entries(params).reduce((text, [name, value]) => {
    return text.replaceAll(`{${name}}`, String(value));
  }, raw);
}

function i18nMap(group) {
  const lang = getCurrentLanguage();
  const maps = I18N_MAPS[group] || {};
  return maps[lang] || maps.es || {};
}

function i18nLookup(group, key, fallback = '') {
  const lang = getCurrentLanguage();
  const maps = I18N_MAPS[group] || {};
  return (maps[lang] && maps[lang][key]) || (maps.es && maps.es[key]) || fallback || key;
}

function i18nPairs(group) {
  const lang = getCurrentLanguage();
  const maps = I18N_MAPS[group] || {};
  return maps[lang] || maps.es || [];
}

function applyI18nToDocument(root = document) {
  document.documentElement.lang = getCurrentLanguage();
  root.querySelectorAll('[data-i18n]').forEach(el => {
    el.textContent = t(el.dataset.i18n);
  });
  root.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    el.setAttribute('placeholder', t(el.dataset.i18nPlaceholder));
  });
  root.querySelectorAll('[data-i18n-title]').forEach(el => {
    el.setAttribute('title', t(el.dataset.i18nTitle));
  });
  root.querySelectorAll('[data-i18n-aria-label]').forEach(el => {
    el.setAttribute('aria-label', t(el.dataset.i18nAriaLabel));
  });
}

function detectedBrowserLanguage() {
  const candidates = [navigator.language, ...(navigator.languages || [])]
    .map(i18nNormalizeLang)
    .filter(lang => I18N_SUPPORTED_PROMPT_LANGS.has(lang));
  return candidates[0] || '';
}

function renderLanguagePrompt() {
  const detected = detectedBrowserLanguage();
  if (!detected || getCurrentLanguage() === detected) return;
  try {
    if (localStorage.getItem(`${I18N_PROMPT_KEY}:${detected}`)) return;
  } catch {}
  const existing = document.querySelector('.language-prompt');
  if (existing) existing.remove();

  const prompt = document.createElement('div');
  prompt.className = 'language-prompt';
  prompt.innerHTML = `
    <div class="language-prompt-title">${t('language.promptTitle')}</div>
    <div class="language-prompt-body">${t('language.promptBody', { language: I18N_LANGUAGES[detected].native })}</div>
    <div class="language-prompt-actions">
      <button type="button" class="language-prompt-accept">${t('language.promptAccept')}</button>
      <button type="button" class="language-prompt-decline">${t('language.promptDecline')}</button>
    </div>`;
  document.body.appendChild(prompt);

  prompt.querySelector('.language-prompt-accept').addEventListener('click', () => {
    try {
      localStorage.setItem(`${I18N_PROMPT_KEY}:${detected}`, 'accepted');
    } catch {}
    setLanguage(detected);
  });
  prompt.querySelector('.language-prompt-decline').addEventListener('click', () => {
    try {
      localStorage.setItem(`${I18N_PROMPT_KEY}:${detected}`, 'declined');
    } catch {}
    prompt.remove();
  });
}

window.I18N_LANGUAGES = I18N_LANGUAGES;
window.getCurrentLanguage = getCurrentLanguage;
window.setLanguage = setLanguage;
window.t = t;
window.i18nMap = i18nMap;
window.i18nLookup = i18nLookup;
window.i18nPairs = i18nPairs;
window.applyI18nToDocument = applyI18nToDocument;
window.renderLanguagePrompt = renderLanguagePrompt;







